CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE feedback_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,source_event_id text NOT NULL,channel text NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feedback_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,customer_id text NOT NULL,service_event_id text NOT NULL,rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),message_redacted text NOT NULL DEFAULT '',sentiment text NOT NULL,risk text NOT NULL,status text NOT NULL,consent_to_contact boolean NOT NULL,opted_out boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),feedback_id uuid NOT NULL REFERENCES feedback_records(id),customer_id text NOT NULL,status text NOT NULL,neutral_template_version text NOT NULL,review_url text NOT NULL,eligible_reason text NOT NULL,scheduled_at timestamptz NOT NULL,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(feedback_id));
CREATE TABLE recovery_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),feedback_id uuid UNIQUE NOT NULL REFERENCES feedback_records(id),customer_id text NOT NULL,severity text NOT NULL,status text NOT NULL,owner text,sla_due_at timestamptz NOT NULL,resolution_code text,resolution_note text,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider_event_id text UNIQUE NOT NULL,feedback_id uuid REFERENCES feedback_records(id),invite_id uuid REFERENCES review_invites(id),event_type text NOT NULL CHECK(event_type IN('review_verified','review_updated','review_removed')),provider text NOT NULL,rating integer CHECK(rating BETWEEN 1 AND 5),occurred_at timestamptz NOT NULL,payload jsonb NOT NULL,evidence_type text NOT NULL CHECK(evidence_type IN('simulated','provider_verified')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid NOT NULL,kind text NOT NULL,attempt_number integer NOT NULL,status text NOT NULL,provider text NOT NULL,error_code text,next_retry_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,kind,attempt_number));
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid,reason text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY,feedback_id uuid REFERENCES feedback_records(id),actor text NOT NULL,action text NOT NULL,evidence_type text NOT NULL CHECK(evidence_type IN('simulated','provider_verified')),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_invites_due ON review_invites(status,scheduled_at);CREATE INDEX idx_cases_sla ON recovery_cases(status,sla_due_at);CREATE INDEX idx_delivery_due ON delivery_attempts(status,next_retry_at);
